def evaluate(expr: str) -> int:
    # ---- Tokenize ----
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
        elif c.isdigit():
            j = i
            while j < n and expr[j].isdigit():
                j += 1
            tokens.append(int(expr[i:j]))
            i = j
        elif c in '+-*/^()':
            tokens.append(c)
            i += 1
        else:
            raise ValueError("unknown character: %r" % c)
    if not tokens:
        raise ValueError("empty input")

    # ---- Recursive descent parser ----
    pos = 0

    def peek():
        return tokens[pos] if pos < len(tokens) else None

    def parse_expr():
        nonlocal pos
        val = parse_term()
        while peek() in ('+', '-'):
            op = tokens[pos]
            pos += 1
            rhs = parse_term()
            val = val + rhs if op == '+' else val - rhs
        return val

    def parse_term():
        nonlocal pos
        val = parse_unary()
        while peek() in ('*', '/'):
            op = tokens[pos]
            pos += 1
            rhs = parse_unary()
            if op == '*':
                val *= rhs
            else:
                if rhs == 0:
                    raise ZeroDivisionError("division by zero")
                q = abs(val) // abs(rhs)
                val = q if (val < 0) == (rhs < 0) else -q
        return val

    def parse_unary():
        nonlocal pos
        if peek() == '-':
            pos += 1
            return -parse_unary()
        return parse_power()

    def parse_power():
        nonlocal pos
        base = parse_atom()
        if peek() == '^':
            pos += 1
            exp = parse_unary()  # right operand may start with unary minus
            if exp < 0:
                raise ValueError("negative exponent")
            return base ** exp
        return base

    def parse_atom():
        nonlocal pos
        t = peek()
        if t == '(':
            pos += 1
            val = parse_expr()
            if peek() != ')':
                raise ValueError("unbalanced parentheses")
            pos += 1
            return val
        if isinstance(t, int):
            pos += 1
            return t
        raise ValueError("missing operand")

    result = parse_expr()
    if pos != len(tokens):
        raise ValueError("unexpected trailing token")
    return result
