import heapq
from collections import defaultdict


def schedule(durations, deps, workers):
    # Validate that every dependency refers to a known task.
    for task, ds in deps.items():
        for d in ds:
            if d not in durations:
                raise ValueError(f"dependency {d!r} of task {task!r} is not in durations")

    remaining = set(durations)                       # tasks not yet finished
    pending = {t: len(deps.get(t, [])) for t in durations}
    dependents = defaultdict(list)                   # task -> tasks waiting on it
    for task, ds in deps.items():
        for d in ds:
            dependents[d].append(task)

    # Ready heap: (-duration, name) so the longest task (smallest name on ties) pops first.
    ready = []
    for t in durations:
        if pending[t] == 0:
            heapq.heappush(ready, (-durations[t], t))

    starts = {}
    running = []                                     # heap of (finish_time, name)
    free = workers
    t = 0

    while remaining:
        if running:
            # Advance to the earliest finish time; all tasks finishing then complete.
            t = running[0][0]
            while running and running[0][0] == t:
                _, name = heapq.heappop(running)
                free += 1
                remaining.discard(name)
                for dep in dependents[name]:
                    pending[dep] -= 1
                    if pending[dep] == 0:
                        heapq.heappush(ready, (-durations[dep], dep))

        # Assign idle workers to ready tasks by priority.
        while free > 0 and ready:
            negd, name = heapq.heappop(ready)
            starts[name] = t
            free -= 1
            heapq.heappush(running, (t + durations[name], name))

        if not running:
            # Nothing running and nothing ready, yet tasks remain -> dependency cycle.
            raise ValueError("dependency cycle detected")

    return (t, starts)
